SELECT sku, gtin, name, pack, case_units, flow, price_inr, cost_inr
FROM store.products
ORDER BY sku;

SELECT audit_ts, sku, status
FROM store.shelf_audits
ORDER BY audit_ts, sku;

SELECT count_ts, sku, book_before, counted, adjustment, trigger
FROM store.stock_counts
ORDER BY count_ts, sku;
